 priority "high" | "low"
 owner Owner?
 created string
 points int
 status "open" | "closed" }
class Metadata { tags string[] }
class CloseInput { id string
 resolution "fixed" | "duplicate"
 metadata Metadata? }
class Ok { ok bool }
class Failure { ok false
 error "timeout" }
class Success { ok true
 ids string[] }
class Filter { priority "high" | "low" }
class QueryInput { filter Filter
 limit int? }
class QueryResult { items Ticket[] }
function Main() -> int { let total = 0; for (let n in [3,1,4,1,5]) { if (n % 2 == 1) { total += n; } } total }

